actions.script:
import java.time.LocalDate
def today = java.sql.Date.valueOf(LocalDate.now())
def expiredSubs = ec.entity.find("zenith.erp.saas.SaasSubscription")
    .condition("statusId", "SubTrial")
    .condition("trialEndDate", "<", today)
    .disableAuthz().list()

// Cancelled subscriptions must stop access at their paid period end, but must never
// cancel a newer active subscription after the tenant changes plans.
ec.entity.find('zenith.erp.saas.SaasSubscription').condition('statusId','SubCancelled')
    .disableAuthz().list().each { cancelled ->
        ec.service.sync().name('zenith.saas.SaasLifecycleServices.expire#CancelledSubscription')
            .parameters([subscriptionId:cancelled.subscriptionId]).disableAuthz().call()
    }
ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('configKey','MANUAL_PLAN_SUBSCRIPTION')
    .disableAuthz().list().each { grant ->
        ec.service.sync().name('zenith.saas.SaasAdminServices.expire#ManualPlan')
            .parameters([tenantId:grant.tenantId]).disableAuthz().call()
    }
int expiredCount = 0
expiredSubs.each { sub ->
    def res = ec.service.sync().name("zenith.saas.SaasLifecycleServices.expire#TrialSubscription")
        .parameters([subscriptionId: sub.subscriptionId, tenantId: sub.tenantId,
                     trialEndDate: sub.trialEndDate])
        .disableAuthz().call()
    if (res?.suspended) expiredCount++
    else ec.logger.warn("SaaS trial expiry: could not suspend tenant ${sub.tenantId} (sub ${sub.subscriptionId})")
}
if (expiredCount > 0) ec.logger.info("SaaS trial expiry: suspended ${expiredCount} tenant(s)")

if (ec.web != null && !ec.user.isInGroup('ADMIN')) { ec.message.addError('Only the platform administrator can run subscription expiry.'); return }
def candidate = ec.entity.find('zenith.erp.saas.SaasSubscription').condition('subscriptionId',subscriptionId).one()
if (!candidate) return
// Match the tenant-first lock order used by plan changes and cancellation.
def tenant = ec.entity.find('zenith.erp.saas.SaasTenant').condition('tenantId',candidate.tenantId).forUpdate(true).one()
def sub = ec.entity.find('zenith.erp.saas.SaasSubscription').condition('subscriptionId',subscriptionId).forUpdate(true).one()
if (!sub || sub.statusId != 'SubCancelled') return
def end = sub.endDate ?: sub.renewalDate ?: sub.trialEndDate
def today = java.sql.Date.valueOf(ec.user.nowTimestamp.toLocalDateTime().toLocalDate())
if (!end || end > today) return
if (ec.entity.find('zenith.erp.saas.SaasSubscription').condition('tenantId',sub.tenantId)
        .condition('statusId','in',['SubActive','SubTrial','SubPastDue']).count() > 0) return
if (!tenant || tenant.statusId == 'SaasTenantCancelled') return
ec.service.sync().name('update#zenith.erp.saas.SaasTenant')
    .parameters([tenantId:sub.tenantId,statusId:'SaasTenantCancelled']).call()
ec.service.sync().name('create#zenith.erp.saas.SaasAuditLog').parameters([
    tenantId:sub.tenantId,eventType:'CANCEL_PERIOD_ENDED',eventDate:ec.user.nowTimestamp,
    description:'Cancelled subscription reached the end of its billing period']).call()

import java.time.LocalDate

def today = java.sql.Date.valueOf(LocalDate.now())
def dueSubs = ec.entity.find("zenith.erp.saas.SaasSubscription")
    .condition("statusId", "SubActive")
    .condition("renewalDate", "<=", today)
    .condition("autoRenew", "Y")
    .list()

int renewedCount = 0
dueSubs.each { sub ->
    def tenant = ec.entity.find("zenith.erp.saas.SaasTenant")
        .condition("tenantId", sub.tenantId).forUpdate(true).one()
    def plan = ec.entity.find("zenith.erp.saas.SaasPlan")
        .condition("planId", sub.planId).one()
    if (!tenant || !plan) return
    if (ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',sub.tenantId)
            .condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()?.configValue) return

    // IDEMPOTENCY: skip if an invoice already exists for this subscription + renewal period,
    // so a re-run / overlapping cron can't double-bill the tenant for one cycle.
    def alreadyBilled = ec.entity.find("zenith.erp.saas.SaasInvoice")
        .condition("subscriptionId", sub.subscriptionId)
        .condition("periodFrom", sub.renewalDate)
        .disableAuthz().count()
    if (alreadyBilled > 0) return

    // Create invoice for the renewal period
    def periodFrom = sub.renewalDate
    def periodToDate = sub.billingCycle == 'Yearly' ?
        LocalDate.parse(periodFrom.toString()).plusYears(1) :
        LocalDate.parse(periodFrom.toString()).plusMonths(1)
    def periodTo = java.sql.Date.valueOf(periodToDate)
    def amount = sub.billingCycle == 'Yearly' ? plan.yearlyPrice : plan.monthlyPrice

    // ZE-SALES-020 (SL-075) sweep: taxableAmount is REQUIRED on calculate#SubscriptionTax. A plan
    // with no price for THIS billing cycle -> amount=null -> the tax call fails input validation and
    // POISONS ec.message; Moqui then refuses to run create#SaasInvoice + the renewal-date update +
    // audit for this sub AND every later sub in the run (one tx -> the whole daily cron rolls back,
    // no tenant billed). Skip + log the mis-priced plan so the rest of the run bills normally.
    if (amount == null) {
        ec.logger.warn("SaaS renewal: plan ${plan.planId} has no ${sub.billingCycle} price; skipping subscription ${sub.subscriptionId} (tenant ${sub.tenantId}) — set the plan price to bill it.")
        return
    }

    // Generate invoice number: max existing suffix +1 within this month's SAAS-yyyyMM- series.
    // (count()+1 REUSED a number whenever any invoice was deleted, and raced on concurrent runs.)
    def _yyyyMM = java.time.LocalDate.now().format(java.time.format.DateTimeFormatter.ofPattern('yyyyMM'))
    def _prefix = 'SAAS-' + _yyyyMM + '-'
    def _lastInv = ec.entity.find("zenith.erp.saas.SaasInvoice")
        .condition("invoiceNumber", "like", _prefix + '%')
        .orderBy("-invoiceNumber").disableAuthz().list()
    int _nextSeq = 1
    if (_lastInv) { try { _nextSeq = (_lastInv[0].invoiceNumber.toString().substring(_prefix.length()) as Integer) + 1 } catch (Exception _ne) { _nextSeq = _lastInv.size() + 1 } }
    def invoiceNumber = _prefix + String.format('%04d', _nextSeq)

    // GST: plan prices are tax-EXCLUSIVE -> add GST on top (18% default for SaaS/SAC 998314).
    // Route through the India GST engine for CGST/SGST vs IGST split by place-of-supply.
    // Falls back to a flat 18% exclusive calc when ZETAERP's GST config / the tenant's
    // state isn't configured, so the TOTAL is always correct even before a GSTIN is set;
    // the head split auto-activates once ZETAERP's GSTIN/state and the tenant's are present.
    def taxOut = ec.service.sync().name("zenith.subscriptions.SubscriptionServices.calculate#SubscriptionTax")
        .parameter("organizationPartyId", "ZETAERP")
        .parameter("customerPartyId", tenant.organizationPartyId)
        .parameter("taxableAmount", amount)
        .parameter("gstRate", 18)
        .disableAuthz().call()
    def _taxAmount = taxOut?.taxAmount ?: 0
    def _totalAmount = taxOut?.totalAmount ?: amount

    def invResult = ec.service.sync().name("create#zenith.erp.saas.SaasInvoice")
        .parameter("tenantId", sub.tenantId)
        .parameter("subscriptionId", sub.subscriptionId)
        .parameter("invoiceNumber", invoiceNumber)
        .parameter("invoiceDate", today)
        .parameter("dueDate", java.sql.Date.valueOf(LocalDate.now().plusDays(7)))
        .parameter("periodFrom", periodFrom)
        .parameter("periodTo", periodTo)
        .parameter("subtotal", amount)
        .parameter("taxAmount", _taxAmount)
        .parameter("cgstAmount", taxOut?.cgstAmount)
        .parameter("sgstAmount", taxOut?.sgstAmount)
        .parameter("igstAmount", taxOut?.igstAmount)
        .parameter("placeOfSupply", taxOut?.placeOfSupply)
        .parameter("totalAmount", _totalAmount)
        .parameter("currencyUomId", sub.currencyUomId ?: tenant.currencyUomId)
        .parameter("statusId", "SiSent")
        .disableAuthz().call()

    // Update subscription renewal date
    ec.service.sync().name("update#zenith.erp.saas.SaasSubscription")
        .parameter("subscriptionId", sub.subscriptionId)
        .parameter("startDate", periodFrom)
        .parameter("renewalDate", periodTo)
        .parameter("amount", amount)
        .parameter("prorationBaseAmount", amount)
        .disableAuthz().call()

    // Audit log
    ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog")
        .parameter("tenantId", sub.tenantId)
        .parameter("eventType", "RENEWAL_INVOICE")
        .parameter("eventDate", ec.user.nowTimestamp)
        .parameter("description", "Renewal invoice created: ${_totalAmount} ${sub.currencyUomId ?: 'INR'} (subtotal ${amount} + GST ${_taxAmount}) for ${periodFrom} to ${periodTo}")
        .disableAuthz().call()

    renewedCount++
}
if (renewedCount > 0) ec.logger.info("SaaS renewal: created ${renewedCount} invoice(s)")

                import java.time.LocalDate

                // Read configurable reminder days
                def renewalDaysSetting = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP")
                    .condition("settingKey", "SAAS_RENEWAL_REMINDER_DAYS").disableAuthz().one()?.settingValue
                def trialDaysSetting = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP")
                    .condition("settingKey", "SAAS_TRIAL_REMINDER_DAYS").disableAuthz().one()?.settingValue
                def renewalReminderDays = (renewalDaysSetting ?: '7') as int
                def trialReminderDays = (trialDaysSetting ?: '3') as int

                def renewalDate = java.sql.Date.valueOf(LocalDate.now().plusDays(renewalReminderDays))
                def oneDayOut = java.sql.Date.valueOf(LocalDate.now().plusDays(1))
                def trialDate = java.sql.Date.valueOf(LocalDate.now().plusDays(trialReminderDays))

                // Find subscriptions renewing in N days
                def threeDaySubs = ec.entity.find("zenith.erp.saas.SaasSubscription")
                    .condition("statusId", "SubActive")
                    .condition("renewalDate", renewalDate)
                    .disableAuthz().list()

                // Find subscriptions renewing tomorrow
                def oneDaySubs = ec.entity.find("zenith.erp.saas.SaasSubscription")
                    .condition("statusId", "SubActive")
                    .condition("renewalDate", oneDayOut)
                    .disableAuthz().list()

                // Find trials expiring in N days
                def trialExpiring = ec.entity.find("zenith.erp.saas.SaasSubscription")
                    .condition("statusId", "SubTrial")
                    .condition("trialEndDate", trialDate)
                    .disableAuthz().list()

                int sent = 0
                // Read email config from settings
                def smtpHost = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP").condition("settingKey", "SAAS_SMTP_HOST").one()?.settingValue
                def smtpPort = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP").condition("settingKey", "SAAS_SMTP_PORT").one()?.settingValue ?: '587'
                def smtpUser = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP").condition("settingKey", "SAAS_SMTP_USER").one()?.settingValue
                def smtpPass = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP").condition("settingKey", "SAAS_SMTP_PASSWORD").one()?.settingValue
                def fromEmail = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP").condition("settingKey", "SAAS_FROM_EMAIL").one()?.settingValue ?: 'noreply@zenitherp.com'
                def fromName = ec.entity.find("zenith.erp.base.CompanySettings")
                    .condition("organizationPartyId", "ZETAERP").condition("settingKey", "SAAS_FROM_NAME").one()?.settingValue ?: 'ZenithERP'
                def emailEnabled = smtpHost && smtpUser

                def sendReminder = { sub, String reminderType ->
                    def tenant = ec.entity.find("zenith.erp.saas.SaasTenant")
                        .condition("tenantId", sub.tenantId).one()
                    if (!tenant || !tenant.adminEmail) return
                    if (ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',sub.tenantId)
                            .condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()?.configValue) return
                    def plan = ec.entity.find("zenith.erp.saas.SaasPlan")
                        .condition("planId", sub.planId).one()

                    if (emailEnabled) {
                        try {
                            def subject = ""
                            def body = ""
                            if (reminderType.contains("Trial")) {
                                subject = "Your ZenithERP trial is expiring soon"
                                body = """Dear ${tenant.tenantName},

Your free trial of ZenithERP ${plan?.planName ?: ''} plan expires on ${sub.trialEndDate}.

To continue using ZenithERP without interruption, please upgrade to a paid plan before your trial ends.

Log in to your account and visit My Subscription to choose a plan.

Thank you,
${fromName}"""
                            } else {
                                subject = "ZenithERP subscription ${reminderType.toLowerCase()}"
                                body = """Dear ${tenant.tenantName},

Your ZenithERP ${plan?.planName ?: ''} subscription (${sub.billingCycle}) is up for renewal on ${sub.renewalDate}.

Amount: ${sub.currencyUomId ?: 'INR'} ${sub.amount}

If you have auto-pay enabled, no action is needed. Otherwise, please ensure payment is made before the renewal date to avoid service interruption.

Thank you,
${fromName}"""
                            }

                            def props = new Properties()
                            props.setProperty("mail.smtp.host", smtpHost)
                            props.setProperty("mail.smtp.port", smtpPort)
                            props.setProperty("mail.smtp.auth", "true")
                            props.setProperty("mail.smtp.starttls.enable", "true")
                            def session = jakarta.mail.Session.getInstance(props,
                                new jakarta.mail.Authenticator() {
                                    protected jakarta.mail.PasswordAuthentication getPasswordAuthentication() {
                                        return new jakarta.mail.PasswordAuthentication(smtpUser, smtpPass)
                                    }
                                })
                            def msg = new jakarta.mail.internet.MimeMessage(session)
                            msg.setFrom(new jakarta.mail.internet.InternetAddress(fromEmail, fromName))
                            msg.setRecipient(jakarta.mail.Message.RecipientType.TO,
                                new jakarta.mail.internet.InternetAddress(tenant.adminEmail))
                            msg.setSubject(subject)
                            msg.setText(body)
                            jakarta.mail.Transport.send(msg)
                        } catch (Exception emailEx) {
                            ec.logger.warn("Failed to send reminder email to ${tenant.adminEmail}: ${emailEx.message}")
                        }
                    }

                    ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog")
                        .parameter("tenantId", sub.tenantId)
                        .parameter("eventType", "REMINDER_SENT")
                        .parameter("eventDate", ec.user.nowTimestamp)
                        .parameter("description", "${reminderType} reminder ${emailEnabled ? 'sent' : 'logged (SMTP not configured)'} to ${tenant.adminEmail}")
                        .disableAuthz().call()

                    ec.logger.info("SaaS reminder: ${reminderType} for tenant ${tenant.tenantName} (${tenant.adminEmail})")
                    sent++
                }

                threeDaySubs.each { sendReminder(it, "Renewal in 3 days") }
                oneDaySubs.each { sendReminder(it, "Renewal tomorrow") }
                trialExpiring.each { sendReminder(it, "Trial expires in 3 days") }

                if (sent > 0) ec.logger.info("SaaS reminders: sent ${sent} reminder(s)")

import java.time.LocalDate

def today = java.sql.Date.valueOf(LocalDate.now())

// Read configurable grace period
def graceDaysSetting = ec.entity.find("zenith.erp.base.CompanySettings")
    .condition("organizationPartyId", "ZETAERP")
    .condition("settingKey", "SAAS_OVERDUE_GRACE_DAYS").disableAuthz().one()?.settingValue
def graceDays = (graceDaysSetting ?: '7') as int
def graceDate = java.sql.Date.valueOf(LocalDate.now().minusDays(graceDays))

// Find invoices past due date (mark as overdue)
def pastDueInvoices = ec.entity.find("zenith.erp.saas.SaasInvoice")
    .condition("statusId", "SiSent")
    .condition("dueDate", "<", today)
    .disableAuthz().list()
pastDueInvoices.each { inv ->
    ec.service.sync().name("update#zenith.erp.saas.SaasInvoice")
        .parameter("saasInvoiceId", inv.saasInvoiceId)
        .parameter("statusId", "SiOverdue")
        .disableAuthz().call()
}

// Find invoices past grace period for suspension
def overdueInvoices = ec.entity.find("zenith.erp.saas.SaasInvoice")
    .condition("statusId", "SiOverdue")
    .condition("dueDate", "<", graceDate)
    .disableAuthz().list()

def tenantsToSuspend = new HashSet()
overdueInvoices.each { inv -> tenantsToSuspend.add(inv.tenantId) }

int suspended = 0
tenantsToSuspend.each { tenantId ->
    def tenant = ec.entity.find("zenith.erp.saas.SaasTenant")
        .condition("tenantId", tenantId).forUpdate(true).one()
    if (!tenant || tenant.statusId != 'SaasTenantActive') return

    // Manual access is controlled by its end date; old invoices remain outstanding.
    if (ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',tenantId)
            .condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()?.configValue) return
    // Suspend tenant
    ec.service.sync().name("update#zenith.erp.saas.SaasTenant")
        .parameter("tenantId", tenantId)
        .parameter("statusId", "SaasTenantSuspended")
        .disableAuthz().call()

    // Update subscription to past due
    def activeSubs = ec.entity.find("zenith.erp.saas.SaasSubscription")
        .condition("tenantId", tenantId)
        .condition("statusId", "SubActive")
        .list()
    activeSubs.each { sub ->
        ec.service.sync().name("update#zenith.erp.saas.SaasSubscription")
            .parameter("subscriptionId", sub.subscriptionId)
            .parameter("statusId", "SubPastDue")
            .disableAuthz().call()
    }

    // Audit log
    ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog")
        .parameter("tenantId", tenantId)
        .parameter("eventType", "AUTO_SUSPEND")
        .parameter("eventDate", ec.user.nowTimestamp)
        .parameter("description", "Auto-suspended due to overdue payment")
        .disableAuthz().call()

    ec.logger.info("SaaS auto-suspend: suspended tenant ${tenant.tenantName} (overdue payment)")
    suspended++
}
if (suspended > 0) ec.logger.info("SaaS auto-suspend: suspended ${suspended} tenant(s)")
